# Let's try using pysat to solve this as a Hamiltonian path problem
# We'll use the SAT approach with cardinality constraints

from pysat.formula import CNF
from pysat.solvers import Glucose3
from pysat.card import CardEnc

n = 6
N = 36

# Precompute knight moves
def knight_moves(cell):
    r, c = divmod(cell, n)
    moves = []
    for dr, dc in [(1,2),(2,1),(2,-1),(1,-2),(-1,-2),(-2,-1),(-2,1),(-1,2)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            moves.append(nr * n + nc)
    return moves

adj = [knight_moves(i) for i in range(N)]

# Variables: x[i][t] means cell i is visited at step t
# We'll use variable numbering: var = i * N + t + 1 (1-indexed for SAT)

def var(i, t):
    return i * N + t + 1

cnf = CNF()

# Each cell appears exactly once in the tour
for i in range(N):
    clause = [var(i, t) for t in range(N)]
    cnf.add_clause(clause)  # at least one
    # at most one: pairwise
    for t1 in range(N):
        for t2 in range(t1+1, N):
            cnf.add_clause([-var(i, t1), -var(i, t2)])

# Each step has exactly one cell
for t in range(N):
    clause = [var(i, t) for i in range(N)]
    cnf.add_clause(clause)  # at least one
    for i1 in range(N):
        for i2 in range(i1+1, N):
            cnf.add_clause([-var(i1, t), -var(i2, t)])

# Start at cell 0 at step 0
cnf.add_clause([var(0, 0)])

# Consecutive steps must be knight moves
for t in range(N-1):
    for i in range(N):
        for j in range(N):
            if j not in adj[i]:
                cnf.add_clause([-var(i, t), -var(j, t+1)])

# Fixed assignments
fixed = {3: 17, 6: 24, 17: 30, 19: 6, 29: 25, 32: 21, 34: 23}
for step, cell in fixed.items():
    cnf.add_clause([var(cell, step)])

print(f"CNF has {len(cnf.clauses)} clauses")

solver = Glucose3()
solver.append_formula(cnf)
result = solver.solve()
print(f"Satisfiable: {result}")

if result:
    model = solver.get_model()
    # Extract solution
    solution = [-1] * N
    for i in range(N):
        for t in range(N):
            if model[var(i, t)-1] > 0:
                solution[t] = i
    print(f"Solution: {solution}")

    # Verify
    # Check all cells visited
    print(f"All cells visited: {sorted(solution) == list(range(N))}")
    # Check start
    print(f"Starts at 0: {solution[0] == 0}")
    # Check knight moves
    ok = True
    for t in range(N-1):
        if solution[t+1] not in adj[solution[t]]:
            print(f"Invalid move at step {t}: {solution[t]} -> {solution[t+1]}")
            ok = False
    print(f"All moves valid: {ok}")
    # Check fixed
    for step, cell in fixed.items():
        print(f"x[{step}] = {solution[step]} (expected {cell}): {solution[step] == cell}")
else:
    print("UNSAT")

